from typing import List
from collections import defaultdict

class Solution:
    def fridayPurchases(self, purchases: List[List[int]], users: List[List[int]]) -> List[List[int]]:
        # purchases rows: [user_id, day, amount]; users rows: [user_id, mem_code]
        fridays = {d: d // 7 + 1 for d in (3, 10, 17, 24)}
        mem = {u[0]: u[1] for u in users}
        total = defaultdict(int)
        for uid, day, amt in purchases:
            if day in fridays and mem.get(uid) in (1, 2):
                total[(fridays[day], mem[uid])] += amt
        return [[w, m, total.get((w, m), 0)] for w in range(1, 5) for m in (1, 2)]

