#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    vector<vector<int>> fridayPurchases(vector<vector<int>>& purchases, vector<vector<int>>& users) {
        unordered_map<int,int> friday = {{3,1},{10,2},{17,3},{24,4}};
        unordered_map<int,int> mem;
        for (auto& u : users) mem[u[0]] = u[1];
        unordered_map<long long,long long> total;
        for (auto& p : purchases) {
            auto it = friday.find(p[1]);
            auto mt = mem.find(p[0]);
            if (it != friday.end() && mt != mem.end() && (mt->second == 1 || mt->second == 2))
                total[(long long)it->second * 10 + mt->second] += p[2];
        }
        vector<vector<int>> res;
        for (int w = 1; w <= 4; ++w)
            for (int m = 1; m <= 2; ++m)
                res.push_back({w, m, (int)total[w * 10 + m]});
        return res;
    }
};

