import java.util.*;

class Solution {
    public List<List<Integer>> fridayPurchases(int[][] purchases, int[][] users) {
        Map<Integer, Integer> friday = Map.of(3, 1, 10, 2, 17, 3, 24, 4);
        Map<Integer, Integer> mem = new HashMap<>();
        for (int[] u : users) mem.put(u[0], u[1]);
        Map<Long, Long> total = new HashMap<>();
        for (int[] p : purchases) {
            Integer w = friday.get(p[1]);
            Integer m = mem.get(p[0]);
            if (w != null && m != null && (m == 1 || m == 2))
                total.merge(w * 10L + m, (long) p[2], Long::sum);
        }
        List<List<Integer>> res = new ArrayList<>();
        for (int w = 1; w <= 4; w++)
            for (int m = 1; m <= 2; m++)
                res.add(Arrays.asList(w, m, total.getOrDefault(w * 10L + m, 0L).intValue()));
        return res;
    }
}

