from typing import List
from collections import defaultdict

class Solution:
    def fridayPurchases(self, purchases: List[List[int]], users: List[List[int]]) -> List[List[int]]:
        grid = {(w, m): 0 for w in range(1, 5) for m in (1, 2)}
        mem = {u[0]: u[1] for u in users}
        agg = defaultdict(int)
        for uid, day, amt in purchases:
            if day % 7 == 3 and mem.get(uid) in (1, 2):  # Nov Fridays: 3,10,17,24
                agg[(day // 7 + 1, mem[uid])] += amt
        for k, v in agg.items():
            grid[k] = v
        return [[w, m, grid[(w, m)]] for w in range(1, 5) for m in (1, 2)]

