public:
    vector<vector<int>> fridayPurchases(vector<vector<int>>& purchases, vector<vector<int>>& users) {
        unordered_map<int,int> mem;
        for (auto& u : users) mem[u[0]] = u[1];
        unordered_map<int,int> grid;
        for (int w = 1; w <= 4; ++w)
            for (int m = 1; m <= 2; ++m)
                grid[w * 10 + m] = 0;
        for (auto& p : purchases) {
            auto mt = mem.find(p[0]);
            if (p[1] % 7 == 3 && mt != mem.end() && (mt->second == 1 || mt->second == 2))
                grid[(p[1] / 7 + 1) * 10 + mt->second] += p[2];
        }
        vector<vector<int>> res;
        for (int w = 1; w <= 4; ++w)
            for (int m = 1; m <= 2; ++m)
                res.push_back({w, m, grid[w * 10 + m]});
        return res;
    }
};

