            if (p[1] % 7 == 3 && m != null && (m == 1 || m == 2)) {
                int key = (p[1] / 7 + 1) * 10 + m;
                grid.merge(key, p[2], Integer::sum);
            }
        }
        List<List<Integer>> res = new ArrayList<>();
        for (int w = 1; w <= 4; w++)
            for (int m = 1; m <= 2; m++)
                res.add(Arrays.asList(w, m, grid.get(w * 10 + m)));
        return res;
    }
}

